PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE review_package (
  id INTEGER PRIMARY KEY,
  created_date DATETIME NOT NULL,
  updated_date DATETIME,
  created_by TEXT NOT NULL,
  updated_by TEXT,
  project_number TEXT,
  municipal_number TEXT,
  review_number INTEGER,
  review_date DATE
, "project_name" TEXT, "status" TEXT, comment TEXT, completed_by TEXT);
CREATE TABLE comments (
  id INTEGER PRIMARY KEY,
  package INTEGER,
  created_date DATETIME NOT NULL,
  updated_date DATETIME,
  created_by TEXT NOT NULL,
  updated_by TEXT,
  comment_id TEXT,
  comment_text TEXT,
  response_text TEXT, "department" TEXT, "status" TEXT,
  FOREIGN KEY (package) REFERENCES review_package(id)
);
CREATE TABLE gis_points (
  id INTEGER PRIMARY KEY,
  created_date DATETIME NOT NULL,
  updated_date DATETIME,
  created_by TEXT NOT NULL,
  updated_by TEXT,
  point_number TEXT NOT NULL,
  northing REAL NOT NULL,
  easting REAL NOT NULL,
  elevation REAL NOT NULL,
  material TEXT NOT NULL,
  witness TEXT,
  project_number TEXT,
  notes TEXT,
  elevation_ngvd29 REAL,
  conversion_factor REAL,
  conversion_sigma REAL,
  latitude REAL NOT NULL,
  longitude REAL NOT NULL,
  source_datum TEXT NOT NULL
, additional_info TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(additional_info)));
CREATE TABLE user_card_favorites (
  user_id TEXT PRIMARY KEY,
  favorites_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(favorites_json)),
  updated_date DATETIME NOT NULL
);
CREATE TABLE invoices (
  id INTEGER PRIMARY KEY,
  invoice_number TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'draft',
  client_name TEXT NOT NULL,
  client_email TEXT NOT NULL,
  project_reference TEXT,
  issue_date DATE NOT NULL,
  due_date DATE,
  notes TEXT,
  internal_note TEXT,
  public_token TEXT NOT NULL UNIQUE,
  subtotal_cents INTEGER NOT NULL DEFAULT 0,
  total_cents INTEGER NOT NULL DEFAULT 0,
  stripe_checkout_session_id TEXT,
  stripe_payment_intent_id TEXT,
  paid_date DATETIME,
  sent_date DATETIME,
  void_date DATETIME,
  created_date DATETIME NOT NULL,
  updated_date DATETIME,
  created_by TEXT NOT NULL,
  updated_by TEXT
, po_number TEXT, previously_billed_cents INTEGER NOT NULL DEFAULT 0, qbo_customer_id TEXT, qbo_project_id TEXT, qbo_invoice_id TEXT, qbo_invoice_sync_token TEXT, qbo_payment_id TEXT, qbo_last_sync_date DATETIME, qbo_sync_status TEXT, qbo_sync_message TEXT, billing_client_name TEXT, billing_email TEXT, billing_address_line1 TEXT, billing_address_line2 TEXT, billing_address_city TEXT, billing_address_state TEXT, billing_address_postal_code TEXT, accounting_sync_state TEXT, project_address_line1 TEXT, project_address_line2 TEXT, project_address_city TEXT, project_address_state TEXT, project_address_postal_code TEXT, email_delivery_state TEXT);
CREATE TABLE invoice_line_items (
  id INTEGER PRIMARY KEY,
  invoice_id INTEGER NOT NULL,
  description TEXT NOT NULL,
  quantity REAL NOT NULL DEFAULT 1,
  unit_amount_cents INTEGER NOT NULL DEFAULT 0,
  amount_cents INTEGER NOT NULL DEFAULT 0,
  sort_order INTEGER NOT NULL DEFAULT 0, contract_amount_cents INTEGER NOT NULL DEFAULT 0, percent_complete REAL NOT NULL DEFAULT 0, bill_in_full INTEGER NOT NULL DEFAULT 0, project_task_id INTEGER,
  FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE
);
CREATE TABLE qbo_connection (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  realm_id TEXT NOT NULL,
  environment TEXT NOT NULL,
  access_token TEXT NOT NULL,
  refresh_token TEXT NOT NULL,
  token_expires_date DATETIME NOT NULL,
  refresh_expires_date DATETIME,
  last_customer_sync_date DATETIME,
  connected_date DATETIME NOT NULL,
  updated_date DATETIME NOT NULL
, last_item_sync_date DATETIME, default_service_item_id TEXT, last_account_sync_date DATETIME, default_deposit_account_id TEXT, stripe_fee_expense_account_id TEXT);
CREATE TABLE qbo_oauth_states (
  state TEXT PRIMARY KEY,
  return_path TEXT,
  created_date DATETIME NOT NULL
);
CREATE TABLE qbo_customers (
  qbo_id TEXT PRIMARY KEY,
  parent_id TEXT,
  display_name TEXT NOT NULL,
  fully_qualified_name TEXT,
  company_name TEXT,
  given_name TEXT,
  family_name TEXT,
  primary_email TEXT,
  primary_phone TEXT,
  bill_addr_line1 TEXT,
  bill_addr_line2 TEXT,
  bill_addr_city TEXT,
  bill_addr_state TEXT,
  bill_addr_postal_code TEXT,
  ship_addr_line1 TEXT,
  ship_addr_line2 TEXT,
  ship_addr_city TEXT,
  ship_addr_state TEXT,
  ship_addr_postal_code TEXT,
  active INTEGER NOT NULL DEFAULT 1,
  sync_token TEXT,
  qbo_updated_time DATETIME,
  last_synced_date DATETIME NOT NULL
);
CREATE TABLE qbo_service_items (
  qbo_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  fully_qualified_name TEXT,
  description TEXT,
  active INTEGER NOT NULL DEFAULT 1,
  sync_token TEXT,
  qbo_updated_time DATETIME,
  last_synced_date DATETIME NOT NULL
);
CREATE TABLE client_contacts (
  id INTEGER PRIMARY KEY,
  qbo_customer_id TEXT NOT NULL,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  phone TEXT,
  role TEXT,
  is_invoice_recipient INTEGER NOT NULL DEFAULT 1,
  active INTEGER NOT NULL DEFAULT 1,
  notes TEXT,
  created_date DATETIME NOT NULL,
  updated_date DATETIME,
  created_by TEXT NOT NULL,
  updated_by TEXT
);
CREATE TABLE invoice_contact_recipients (
  id INTEGER PRIMARY KEY,
  invoice_id INTEGER NOT NULL,
  contact_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE,
  FOREIGN KEY (contact_id) REFERENCES client_contacts(id)
);
CREATE TABLE project_managers (
  qbo_project_id TEXT PRIMARY KEY,
  manager_name TEXT NOT NULL,
  manager_email TEXT NOT NULL,
  updated_date DATETIME NOT NULL,
  updated_by TEXT NOT NULL
);
CREATE TABLE project_billing_profiles (
  qbo_project_id TEXT PRIMARY KEY,
  po_number TEXT,
  invoice_document_note TEXT,
  updated_date DATETIME NOT NULL,
  updated_by TEXT NOT NULL
);
CREATE TABLE project_invoice_documents (
  id INTEGER PRIMARY KEY,
  qbo_project_id TEXT NOT NULL,
  r2_key TEXT NOT NULL UNIQUE,
  filename TEXT NOT NULL,
  content_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL DEFAULT 0,
  active INTEGER NOT NULL DEFAULT 1,
  created_date DATETIME NOT NULL,
  created_by TEXT NOT NULL,
  updated_date DATETIME,
  updated_by TEXT
);
CREATE TABLE invoice_payments (
  id INTEGER PRIMARY KEY,
  invoice_id INTEGER NOT NULL,
  kind TEXT NOT NULL DEFAULT 'payment',
  status TEXT NOT NULL DEFAULT 'succeeded',
  method TEXT NOT NULL,
  gross_cents INTEGER NOT NULL DEFAULT 0,
  fee_cents INTEGER NOT NULL DEFAULT 0,
  net_cents INTEGER NOT NULL DEFAULT 0,
  paid_date DATETIME NOT NULL,
  stripe_checkout_session_id TEXT,
  stripe_payment_intent_id TEXT,
  stripe_charge_id TEXT,
  stripe_balance_transaction_id TEXT,
  qbo_payment_id TEXT,
  qbo_deposit_id TEXT,
  qbo_sync_status TEXT,
  qbo_sync_message TEXT,
  qbo_last_sync_date DATETIME,
  note TEXT,
  created_date DATETIME NOT NULL,
  updated_date DATETIME,
  created_by TEXT NOT NULL,
  updated_by TEXT, stripe_payout_id TEXT, stripe_payout_status TEXT, stripe_payout_reconciled_date DATETIME, accounting_notification_sent_date DATETIME, reference_number TEXT, accounting_sync_state TEXT,
  FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE
);
CREATE TABLE qbo_accounts (
  qbo_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  fully_qualified_name TEXT,
  account_type TEXT,
  account_sub_type TEXT,
  classification TEXT,
  active INTEGER NOT NULL DEFAULT 1,
  sync_token TEXT,
  qbo_updated_time DATETIME,
  last_synced_date DATETIME NOT NULL
);
CREATE TABLE stripe_payouts (
  stripe_payout_id TEXT PRIMARY KEY,
  status TEXT NOT NULL,
  amount_cents INTEGER NOT NULL DEFAULT 0,
  arrival_date DATETIME,
  paid_date DATETIME,
  reconciled_date DATETIME,
  qbo_deposit_id TEXT,
  qbo_sync_status TEXT,
  qbo_sync_message TEXT,
  qbo_last_sync_date DATETIME,
  email_sent_date DATETIME,
  created_date DATETIME NOT NULL,
  updated_date DATETIME
, accounting_sync_state TEXT);
CREATE TABLE project_lifecycle (
  qbo_project_id TEXT PRIMARY KEY,
  status TEXT NOT NULL CHECK (status IN ('proposal', 'active', 'hold', 'complete', 'cancelled')),
  updated_date DATETIME NOT NULL,
  updated_by TEXT NOT NULL,
  FOREIGN KEY (qbo_project_id) REFERENCES qbo_customers(qbo_id)
);
CREATE TABLE project_property_profiles (
  qbo_project_id TEXT PRIMARY KEY,
  parcel_id TEXT NOT NULL DEFAULT '',
  updated_date DATETIME NOT NULL,
  updated_by TEXT NOT NULL,
  FOREIGN KEY (qbo_project_id) REFERENCES qbo_customers(qbo_id)
);
CREATE TABLE project_tasks (
  id INTEGER PRIMARY KEY,
  qbo_project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  scope_of_work TEXT NOT NULL DEFAULT '',
  contract_amount_cents INTEGER NOT NULL DEFAULT 0,
  retainer_cents INTEGER NOT NULL DEFAULT 0,
  price_type TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 0,
  active INTEGER NOT NULL DEFAULT 1,
  created_date DATETIME NOT NULL,
  updated_date DATETIME NOT NULL,
  created_by TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  FOREIGN KEY (qbo_project_id) REFERENCES qbo_customers(qbo_id)
);
CREATE TABLE stripe_webhook_events (
  stripe_event_id TEXT PRIMARY KEY,
  event_type TEXT NOT NULL,
  payment_intent_id TEXT,
  created_date DATETIME NOT NULL
);
CREATE TABLE stripe_payment_lifecycle_notifications (
  stripe_payment_intent_id TEXT NOT NULL,
  lifecycle_state TEXT NOT NULL,
  sent_date DATETIME NOT NULL,
  PRIMARY KEY (stripe_payment_intent_id, lifecycle_state)
);
CREATE TABLE invoice_report_runs (report_date TEXT PRIMARY KEY, status TEXT NOT NULL, created_date TEXT NOT NULL, sent_date TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_review_package_id ON review_package(id);
CREATE INDEX idx_comments_package ON comments(package);
CREATE INDEX idx_gis_points_id ON gis_points(id);
CREATE INDEX idx_gis_points_point_number ON gis_points(point_number);
CREATE INDEX idx_gis_points_project_number ON gis_points(project_number);
CREATE INDEX idx_user_card_favorites_updated_date ON user_card_favorites(updated_date);
CREATE INDEX idx_invoices_invoice_number ON invoices(invoice_number);
CREATE INDEX idx_invoices_status ON invoices(status);
CREATE INDEX idx_invoices_client_email ON invoices(client_email);
CREATE INDEX idx_invoices_public_token ON invoices(public_token);
CREATE INDEX idx_invoices_stripe_checkout_session_id ON invoices(stripe_checkout_session_id);
CREATE INDEX idx_invoices_stripe_payment_intent_id ON invoices(stripe_payment_intent_id);
CREATE INDEX idx_invoice_line_items_invoice_id ON invoice_line_items(invoice_id);
CREATE INDEX idx_invoices_po_number ON invoices(po_number);
CREATE INDEX idx_qbo_customers_parent_id ON qbo_customers(parent_id);
CREATE INDEX idx_qbo_customers_display_name ON qbo_customers(display_name);
CREATE INDEX idx_qbo_customers_primary_email ON qbo_customers(primary_email);
CREATE INDEX idx_qbo_service_items_name ON qbo_service_items(name);
CREATE INDEX idx_client_contacts_qbo_customer_id ON client_contacts(qbo_customer_id);
CREATE INDEX idx_client_contacts_email ON client_contacts(email);
CREATE INDEX idx_invoice_contact_recipients_invoice_id ON invoice_contact_recipients(invoice_id);
CREATE INDEX idx_project_managers_email ON project_managers(manager_email);
CREATE INDEX idx_invoices_qbo_customer_id ON invoices(qbo_customer_id);
CREATE INDEX idx_invoices_qbo_project_id ON invoices(qbo_project_id);
CREATE INDEX idx_invoices_qbo_invoice_id ON invoices(qbo_invoice_id);
CREATE INDEX idx_project_invoice_documents_project_id ON project_invoice_documents(qbo_project_id);
CREATE INDEX idx_invoice_payments_invoice_id ON invoice_payments(invoice_id);
CREATE INDEX idx_invoice_payments_stripe_session ON invoice_payments(stripe_checkout_session_id);
CREATE INDEX idx_invoice_payments_stripe_intent ON invoice_payments(stripe_payment_intent_id);
CREATE UNIQUE INDEX idx_invoice_payments_unique_stripe_session
  ON invoice_payments(stripe_checkout_session_id)
  WHERE stripe_checkout_session_id IS NOT NULL AND stripe_checkout_session_id != '';
CREATE UNIQUE INDEX idx_invoice_payments_unique_stripe_intent
  ON invoice_payments(stripe_payment_intent_id)
  WHERE stripe_payment_intent_id IS NOT NULL AND stripe_payment_intent_id != '';
CREATE INDEX idx_qbo_accounts_name ON qbo_accounts(name);
CREATE INDEX idx_qbo_accounts_account_type ON qbo_accounts(account_type);
CREATE INDEX idx_invoice_payments_stripe_balance_transaction ON invoice_payments(stripe_balance_transaction_id);
CREATE INDEX idx_invoice_payments_stripe_payout ON invoice_payments(stripe_payout_id);
CREATE INDEX idx_project_lifecycle_status ON project_lifecycle(status);
CREATE INDEX idx_project_property_profiles_parcel_id ON project_property_profiles(parcel_id);
CREATE INDEX idx_project_tasks_project_active ON project_tasks(qbo_project_id, active, sort_order);
CREATE INDEX idx_invoice_line_items_project_task_id ON invoice_line_items(project_task_id);
CREATE INDEX idx_stripe_webhook_events_payment_intent
  ON stripe_webhook_events(payment_intent_id);
