INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(21,3,'2026-04-04T00:47:37.552Z','2026-04-24T15:03:42.672Z','Nathan White','Nathan White','2',replace('On the Boundary Survey it identifies the Quarter Section Line (North Line NE 1/4, Sec 9-22-35), however, the proposed plat does not.\nF.S. 177.091 (14) All Section Lines and Quarter Section Lines occurring within the subdivision shall be indicated by lines drawn upon the map or plat, with appropriate words and figures.\nUpdate the plat to include the Quarter Section Line.','\n',char(10)),'Callout added to plat.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(22,3,'2026-04-04T00:47:37.551Z','2026-04-24T15:03:42.803Z','Nathan White','Nathan White','1',replace('The legal description was updated/ changed and does not meet the Florida Statute (F.S.) requirements.\nF.S. 177.091 (11)  Each plat shall show a description of the lands subdivided, and the description shall be the same in the title certification.  The description must be so complete that from it, without reference to the plat, the starting point and boundary can be determined.\nUpdate the Plat to ensure compliance to F.S. 177.091 (11) and provide the acreage and square footage.','\n',char(10)),'Revised legal description provided. Updated title provided as well.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(23,3,'2026-04-04T00:47:37.554Z','2026-04-24T15:03:42.743Z','Nathan White','Nathan White','1',replace('Repeat Comment: Please update the following in section 13.4.1, the roads are not public and will be maintained by the association. \nROADWAYS WITHIN THE COMMUNITY SHALL BE PUBLIC ROADWAYS AND SHALL NOT BE MAINTAINED OR REGULATED BY THE ASSOCIATION. EACH OWNER BY THE ACCEPTANCE OF A DEED TO THEIR HOME ACKNOWLEDGES AND AGREES THE ASSOCIATION HAS NO CONTROL WITH REGARD TO ACCESS, PARKING AND USAGE OF SUCH ROADWAYS BY THE GENERAL PUBLIC AND/OR MEMBERS OF THE ASSOCIATION. THE RESPONSIBILITY FOR ENFORCEMENT OF ANY LAWS REGARDING ACCESS, PARKING AND USAGE OF PUBLIC ROADWAYS RESTS SOLELY WITH THE APPLICABLE GOVERNMENTAL AUTHORITY AND THE ASSOCIATION DISCLAIMS RESPONSIBILITY FOR SUCH ENFORCEMENT.','\n',char(10)),'Langugage in section revised.','Public Works','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(24,3,'2026-04-04T00:47:37.544Z','2026-04-24T15:03:42.750Z','Nathan White','Nathan White','1','Have there been any changes to the previously approved site plan?','No','Fire','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(25,3,'2026-04-04T00:47:37.611Z','2026-04-24T15:03:42.826Z','Nathan White','Nathan White','4',replace('Acknowledge.  Lots one (1) through lot twenty are double frontage lots.\nA six-foot high masonry wall (or equivalent) within the Landscape Easement, across which there shall be no right of access, shall be provided.  [LDR Sec. 30-134]\nNote: Comment #4 is just an informative comment and does not impact the platting process.','\n',char(10)),'Acknowledged','Planning','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(26,3,'2026-04-04T00:47:37.612Z','2026-04-24T15:03:42.744Z','Nathan White','Nathan White','6',replace('Within the Declaration of Covenants, Conditions and Restrictions, Section Thirteen (13), Section 13.34 Signs and Flags.  \nF.S. 720.3075 (3)(a)  Prohibited Clauses in Association Documents. The display of up to two portable, removable flags as described in s. 720.304(2)(a) by property owners. However, all flags must be displayed in a respectful manner consistent with the requirements for the United States flag under 36 U.S.C. chapter 10.\nUpdate Declaration of Covenants, Conditions and Restrictions to include said language.','\n',char(10)),'Section updated.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(27,3,'2026-04-04T00:47:37.599Z','2026-04-24T15:03:42.803Z','Nathan White','Nathan White','1','Section 10.4.2.1 references an easement to government agencies for the road, signs, speed but this is a private road.','Section removed from the CCR.','Water Resources - Utility Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(28,3,'2026-04-04T00:47:37.615Z','2026-04-24T15:03:42.803Z','Nathan White','Nathan White','3',replace('Update the Plat to include the Front Yard and Side Corner Yard Setbacks.\nFront and side setbacks adjacent to streets shall be shown on all plats as required by Chapter 34, Procedures, Article IV, Subdivisions.  [Land Development Regulations, Section 30-138]','\n',char(10)),'Setbacks added based on latest civil planset.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(29,3,'2026-04-04T00:47:37.618Z','2026-04-24T15:03:42.803Z','Nathan White','Nathan White','5',replace('Within the Declaration of Covenants, Conditions and Restrictions, Section Five (5), 5.3 Amendments Prior to the Turnover and 5.4 Amendments After the Turnover, neither of these sections state the requirement to notify the City of Titusville.\nSaid deed restrictions shall include a provision requiring the owners of property in the subdivision to notify and obtain the City Council''s approval of any and all changes, amendments or alterations to the deed restrictions.  [LDR Sec. 34-173 (e)]\nUpdate the Declaration of Covenants, Conditions and Restrictions to include said language.','\n',char(10)),'CCR updated to include said language.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(30,4,'2026-06-11T22:14:41.603Z','2026-06-11T22:14:41.603Z','Nathan White','Nathan White','38','Distance from centerline must be shown and identified. Sec.122-216 (c)(1)','Distances added.','ENG - Real Estate','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(31,4,'2026-06-11T22:14:41.604Z','2026-06-11T22:14:41.604Z','Nathan White','Nathan White','40','Fractional breakdown description including parcel ID number and official records book and page, property line bearings, and property dimensions for the subject property. Section lines, section corners and quarter section corners and quarter section corners must be shown, as appropriate. Sec. 122-216 (a) (3)','Informationa added','ENG - Real Estate','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(32,4,'2026-06-11T22:14:41.597Z','2026-06-11T22:14:41.597Z','Nathan White','Nathan White','7','The subject parcel appears to lie within two FEMA Flood Insurance Rate Maps. Please revise the FEMA FIRM INFORMATION: depicted on the Boundary & Topographic Survey to be in agreement with the FEMA MAP information depicted on the Cover Sheet (C-0.0) of the Civil Plans set.','Both FEMA maps have been referenced in note 5','ENG - Survey','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(33,4,'2026-06-11T22:14:41.602Z','2026-06-11T22:14:41.602Z','Nathan White','Nathan White','13','"NW 11TH ST" as depicted on the Boundary & Topographic Survey appears to be in error and is not in agreement with the Marion County Property Appraiser - Map It+ website. Please review and revise the Boundary & Topographic Survey as appropriate.','Not sure what this is referencing, however new survey should cover this comment. Please advise further if this comment is not addressed.','ENG - Survey','further information');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(34,4,'2026-06-11T22:14:41.603Z','2026-06-11T22:14:41.603Z','Nathan White','Nathan White','37','Adjacent streets must be shown and identified. Sec.122-216','The survey is limited to that which the surveyor was made aware of in the normal course of performing a land survey.','ENG - Real Estate','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(35,4,'2026-06-11T22:14:41.685Z','2026-06-11T22:14:41.685Z','Nathan White','Nathan White','34','Easements must be shown and labeled with Plat Book and page or ORB and Page #, type of easement.  All easements on the subject property and easement on abutting property that could  be affected by the development must be shown and labeled. Sec.122-216','Surveyor was not provided a title document for review. As such, the survey is limited to that which the surveyor was made aware of in the normal course of performing a land survey.','ENG - Real Estate','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(36,4,'2026-06-11T22:14:41.694Z','2026-06-11T22:14:41.694Z','Nathan White','Nathan White','39','Show width of existing rights-of-way and any proposed future rights-of-way that may affect the development. Sec.122-216','Information added','ENG - Real Estate','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(37,4,'2026-06-11T22:14:41.678Z','2026-06-11T22:14:41.678Z','Nathan White','Nathan White','12','The legal description of the subject parcel is included. (Please include the book and page number of the recording document used, if applicable. If the legal description is prepared by the surveyor, please so state.) 122-216 (a); 1) Please include a reference to the recording document for the legal description depicted in metes and bounds format OR if the legal description was prepared by the Surveyor of Record, please so state as required by the City Code. 2) "TOWNSHIP 135 SOUTH" as depicted in the legal description on the Cover Sheet (Sheet Number: C-0.0) of the Civil Plans set and the Boundary & Topographic Survey depicted on the Existing Conditions Sheet (Sheet Number: C-1.0) of the Civil Plans set appears to be in error and was intended to be "TOWNSHIP 15 SOUTH". Please review and revise the Civil Plans set and Boundary & Topographic Survey accordingly.','1. ORB & Page reference added. 2. Typo corrected.','ENG - Survey','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(38,4,'2026-06-11T22:14:41.688Z','2026-06-11T22:14:41.688Z','Nathan White','Nathan White','10','Easements shown on the survey must be shown and labeled on the site plan when affected. Specific Information required on the Site Plan as referenced in Sec. 122-216(f)(1) of the City Code: All easements on the subject property, and on the abutting property that could be affected by the development, shall be shown and labeled with the following information: a. The type of easement; and b. the plat book and page or official records book and page. Please show and label on the Site Plan set and / or Boundary & Topographic Survey all easements that could be affected by the development as required by the City Code. 1) Please revise the Civil Plans set to include an Official Records Book and page reference in the labeling of the "24'' WIDE ACCESS EASEMENT" or if said easement is "PROPOSED" please label said easement accordingly. 2) Please revise the Civil Plans set to define / label the limits of the boundary of said "24'' WIDE ACCESS EASEMENT".','Survey added 24'' proposed easement.','ENG - Survey','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(39,4,'2026-06-11T22:14:41.681Z','2026-06-11T22:14:41.681Z','Nathan White','Nathan White','6','Comments noted herein associated with the review of survey matters reflect the interpretation by the City of Ocala Survey Division of applicable statutes, codes and regulations governing the performance of surveys that accompany development applications; such matters have subjective elements that may result in a difference of opinion with the Surveyor of Record; in the event of such difference, the Surveyor of Record is strongly encouraged to reach out directly to the reviewer to openly discuss and explore options to resolve the comment to the satisfaction of both parties.','Comment Noted','ENG - Survey','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(40,4,'2026-06-11T22:14:41.689Z','2026-06-11T22:14:41.689Z','Nathan White','Nathan White','35','Property adjacent to subject property must be identified and labeled on the site plan drawing with subdivision name, block number (s), lot number(s) or parcel ID# and the phrase "not platted" for non-platted land. Sec.122-216','Requested information added.','ENG - Real Estate','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(41,4,'2026-06-11T22:14:41.695Z','2026-06-11T22:14:41.695Z','Nathan White','Nathan White','9','The boundary is tied to state plane coordinates. Include the coordinates at the ends of at least one boundary line. 122-215 (e); Please provide Florida State Plane Coordinates, NAD 83 Datum, Florida West Zone at each end of at least one boundary line as required by the City Code.','Coordinates added. See NE corner and the corner directly south. CCR corners and bearing have also been added.','ENG - Survey','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(42,5,'2026-07-27T17:33:32.949Z','2026-08-02T19:34:36.210Z','Nathan White','Nathan White','1','On Sheet A3, the callouts on the foundation, shall be tied to a schedule or referenced to a plan page. Update accordingly. CODE: Notes and legends must be keys to the plan pages and details (FBC 107.2.1)','References to a plan page have been added to sheet A3.','Building Review (Res)','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(43,5,'2026-07-27T17:33:32.961Z','2026-08-02T19:34:36.234Z','Nathan White','Nathan White','2',replace('1.-On sheet A6, the information provided on the top, left side, is not legible. Please correct.\n2.-On sheet SN, the information provided on the top, left side, is not legible. Please correct.\nCode: The plans submitted are not legible. Please provide legible plans and plan notes when resubmitting. (FBC \n107.2.1)','\n',char(10)),'Both A6 and SN have been re-plotted to PDF and verified readable on our side.','Building Review (Res)','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(44,5,'2026-07-27T17:34:23.820Z','2026-08-02T19:34:36.155Z','Nathan White','Nathan White','3',replace('ISSUE: Please clarify the use of Kennel, if this is a commercial or residential.\nCODE: Notes and details shall be specific to the individual project. Under no circumstances shall plan notes or \ndetails cite the code section only or include phrases such as "or equal" or "as per (local) code". (FBC 107.2.1)','\n',char(10)),'Callout for private kennal added to Sheet A2 and PLOT PLAN.','Building Review (Res)','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(45,5,'2026-07-27T17:34:23.832Z','2026-08-02T19:34:36.089Z','Nathan White','Nathan White','4','For information when submitting corrections or revisions, please upload a Narrative addressing each denial comment along with your corrected plans. Denial comment responses must be submitted electronically through the Orange County FastTrack system. Unsupported or vague narrative responses may prompt a redenial of the same comment. If you feel a denial comment is incorrect please respond with the specific section of the code to support your claim or if it is not a code related comment, provide a detailed response as to why the comment does not apply.  Additional review may be necessary upon review of corrected plans.','See this document.','Building Review (Res)','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(46,5,'2026-07-27T17:36:20.761Z','2026-08-02T19:34:36.160Z','Nathan White','Nathan White','5','Proposed development is in uplands authorized by CAI-22-08-058 and does not impact authorized upland buffer. Approval of this building permit does not authorize future impacts to the upland buffer or wetlands on site.','Acknowledged.','EPD','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(47,5,'2026-07-27T17:36:20.756Z','2026-08-02T19:34:36.212Z','Nathan White','Nathan White','6','The provided Ranger Drainage District (RDD) permit did not have a stamped, authorized survey. Please provide the stamped survey approved through the RDD permit to ensure there will not be issues with drainage into the wetlands.','A stamped survey is provided in this submittal. Client to handle RDD permit.','EPD','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(48,5,'2026-07-27T17:39:17.037Z','2026-08-02T19:34:36.161Z','Nathan White','Nathan White','7','Site plan to include location of Onsite Sewage Disposal Systems (all components); Septic tank and drain field.','Septic tank and drainfield added to PLOT PLAN.','Health','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(49,5,'2026-07-27T17:39:17.042Z','2026-08-02T19:34:36.158Z','Nathan White','Nathan White','10 (Zoning 3)','Pending submission of corrections, more comments may be generated.','Acknowledged.','Zoning','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(50,5,'2026-07-27T17:39:17.047Z','2026-08-02T19:34:36.165Z','Nathan White','Nathan White','9 (Zoning 2)',replace('Location of AC equipment, and screening requirement are missing from PD-Survey.\nSOLUTION:\n1. Clearly show the location of AC equipment, \n2. Clearly draw the screening requirement of choice. \n3. Show the setback from the equipment to the side property line. \n4.  Label it as either "100% opaque vegetative buffer", The fence permit number, or wall permit number. \nIf A wall or fence is being proposed, a separate permit must be obtained. The permit number must be indicated on the site plan.','\n',char(10)),replace('1. AC equipment pads added.\n2. 100% opaque vegitatve buffer note added.\n3. Setback added to PLOT PLAN\n4. Label added. No fence or wall is proposed.','\n',char(10)),'Zoning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(51,5,'2026-07-27T17:39:17.043Z','2026-08-02T19:34:36.160Z','Nathan White','Nathan White','8 ( Zoning 1)','Location of AC equipment does not match between plans.','A2 "DIMENSIONS" section is source of truth. PLOT PLAN updated to reflect A2.','Zoning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(52,5,'2026-07-27T17:40:21.140Z','2026-08-02T19:34:36.155Z','Nathan White','Nathan White','11 (Zoning 4)','Multiple information comments not printed.','All comments acknowledged.','Zoning','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(53,6,'2026-08-06T23:08:46.810Z','2026-08-07T14:09:55.096Z','Nathan White','Nathan White','2',replace('On the proposed Plat Cover Sheet, the Certificate of Reviewing Surveyor for the City of Titusville; update this as follows:\na. Replace the statement, Examined and Approved'' with  I HEREBY CERTIFY, That I have examined the foregoing plat and find that it is in conformity with Chapter 177, part 1, Florida Statutes ;\nb. Replace County Surveyor'' with Reviewing Surveyor for the City of Titusville ;\nc. Underneath Reviewing Surveyor for the City of Titusville'', add Lynn Sanders, PLS 4863;','\n',char(10)),'The first sheet has been completely changed. This comment is acknoweldged and addressed.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(54,6,'2026-08-06T23:08:46.811Z','2026-08-07T14:09:55.094Z','Nathan White','Nathan White','1',replace('On the proposed Plat Cover Sheet, underneath the Dedication section, the Certificate of Surveyor section; replace this section with your Qualification Statement of Surveyor and Mapper.''  \n\nThe Certificate of Surveyor section was intended for the qualification statement and surveyor''s seal.','\n',char(10)),'The first sheet has been completely changed. This comment is acknoweldged and addressed.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(55,6,'2026-08-06T23:15:28.279Z','2026-08-12T13:56:34.262Z','Nathan White','Nathan White','12',replace('The proposed Lot Area and Lot Widths have changed.  Provide the Maximum Impervious Area for each lot.\nThat each site/subdivision must calculate the maximum impervious area for each lot(s).  This information must be included on site plan and/or plat.  [LDR Sec. 30-208 (14)]','\n',char(10)),'A revised site plan and PSP have been submitted to the city prior to the submittal of this revised final plat.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(56,6,'2026-08-06T23:15:28.283Z','2026-08-07T14:09:55.092Z','Nathan White','Nathan White','9',replace('On the proposed Plat Sheets 2, 3 and 4, within the Title section, after the Section, Township, and Range, add the City of Titusville before Brevard County.\nThe Section, Township, and Range shall appear immediately under the name of the plat on each sheet included, along with the name of the City, Town, Village, County, and State in which the land being platted is situated.  [FS 177.091 (10)]','\n',char(10)),'The plat has been completely changed. This comment is addressed and acknowledged.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(57,6,'2026-08-06T23:15:28.298Z','2026-08-07T14:09:55.091Z','Nathan White','Nathan White','10',replace('On the proposed Plat Sheets 2, 3 and 4, the following items are not needed and can be removed:\na. the Dedication section;\nb. Certificate of Surveyor''s section;\nc. Certificate of Reviewing Surveyor for the City of Titusville section;\nd. Certificate of Clerk section;\ne. Certificate of Approval Engineer section;\nf.  Qualification Statement of Surveyor and Mapper section;','\n',char(10)),'The plat has been completely changed. This comment is addressed and acknowledged.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(58,6,'2026-08-06T23:15:28.297Z','2026-08-07T14:09:55.099Z','Nathan White','Nathan White','8',replace('When more than one sheet must be used to accurately portray the lands subdivided, an index or key map must be included and each sheet must show the particular number of that sheet and the total number of sheets included, as well as clearly labeled matchlines to show where other sheets match or adjoin.   [FS 177.091 (3)]\nUpdate the Plat to add the Index or Key Map and the Match Lines.','\n',char(10)),'The plat has been completely changed. This comment is addressed and acknowledged.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(59,6,'2026-08-06T23:15:28.302Z','2026-08-07T14:09:55.096Z','Nathan White','Nathan White','4',replace('On the proposed Plat Cover Sheet, why are there Line and Curve Tables placed here.\nWhen it is not possible to show line or curve data information on the map, a tabular form may be used. The tabular data must appear on the sheet to which it applies. [Florida Statute (FS) 177.091 (26)]\nRemove the Line and Curve Tables from the Cover Sheet and place them on the appropriate plat sheets.','\n',char(10)),'The first sheet has been completely changed. This comment is acknoweldged and addressed.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(60,6,'2026-08-06T23:15:28.315Z','2026-08-07T14:09:55.094Z','Nathan White','Nathan White','7','Provide a Table called  Tract Designation''.  The Column Labels are as such: Tract; Description (i.e. Open Space, Alley Way, Stormwater); Square Feet; Acres; Owned By; Maintained By.','The first sheet has been completely changed. This comment is acknoweldged and addressed.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(61,6,'2026-08-06T23:15:28.320Z','2026-08-07T14:09:55.089Z','Nathan White','Nathan White','3','On the proposed Plat Cover Sheet, remove the Certificate of Approval Engineer'' section.','The first sheet has been completely changed. This comment is acknoweldged and addressed.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(62,6,'2026-08-06T23:15:28.327Z','2026-08-12T13:56:34.258Z','Nathan White','Nathan White','1',replace('Sec. 30-207.(a)(14)That each site/subdivision must calculate the maximum impervious area for each lot(s). This information must be included on site plan and/or plat.\nCOMMENT: Please add the impervious breakdown per lot as a note, reference or tabular exhibit','\n',char(10)),'A impervious area report is provided with this submittal.','Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(63,6,'2026-08-06T23:15:28.330Z','2026-08-07T14:09:55.091Z','Nathan White','Nathan White','6','On the proposed Plat Cover Sheet, within the Notes, add a note stating where to find the Protective Covenants and Restrictions.','The first sheet has been completely changed. This comment is acknoweldged and addressed.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(64,6,'2026-08-06T23:15:28.332Z','2026-08-07T14:09:55.095Z','Nathan White','Nathan White','13',replace('The proposed revision to Section 5.1,  Notwithstanding any other provision herein to the contrary, and pursuant to all applicable ordinances of City, including, Section 34-173(e) (Required Exhibits; Deed Restrictions) of the City code, no amendment to this Declaration shall affect the rights of Declarant unless such amendment receives the prior written consent of Declarant, which consent may be withheld for any reason whatsoever. , does not meet standard of notifying and obtaining City Council''s approval of proposed changes.\nRepeat Comment.  In the proposed Declaration of Covenants, Conditions, and Restrictions (CC&Rs), Section 5, Amendment, update Section 5.1 to include language that meets the following requirement.\nDeed Restrictions shall include a provision requiring the owners of property in the subdivision to notify and obtain the City Council''s approval of any and all changes, amendments or alterations to the deed restrictions.  [LDR Sec. 34-173 (e)]','\n',char(10)),'Language adjusted.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(65,6,'2026-08-06T23:15:28.334Z','2026-08-12T13:56:34.261Z','Nathan White','Nathan White','15',replace('City Maximum Impervious Area Table for Each Lot; this data is incorrect.\nThis data does not match the Preliminary Plat nor the Site Plan.  Furthermore, it does not provide the Maximum amount of allowable impervious surface coverage per lot.  [LDR Sec. 30-207 (a)(14)]\nUpdate Exhibit 5 to meet the minimum standards.','\n',char(10)),'A impervious area report is provided with this submittal.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(66,6,'2026-08-06T23:15:28.335Z','2026-08-07T14:09:55.097Z','Nathan White','Nathan White','5','On the proposed Plat Cover Sheet, the Legal Description, at the end of the legal description, after the point of beginning, add the acreage and square footage.','The first sheet has been completely changed. This comment is acknoweldged and addressed.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(67,6,'2026-08-06T23:15:28.335Z','2026-08-07T14:09:55.087Z','Nathan White','Nathan White','14',replace('Repeat Comment. CC&Rs Section 16 Assessments.  Provide information within the CC&Rs where it addresses the maintenance responsibility of the Private Street.\nPrivate Streets. The subdivider demonstrates to the satisfaction of the Planning and Zoning Commission and City Council that the private roads will be properly maintained.  At a minimum, a provision for same shall be incorporated in the articles of the maintenance association. (See [Article I, Division 3,] Operating and Maintenance of this chapter.)   [LDR Sec. 30-237(c)(4)]','\n',char(10)),'Language adjusted','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(68,6,'2026-08-06T23:15:28.336Z','2026-08-07T14:09:55.089Z','Nathan White','Nathan White','16',replace('The recorded plat of any subdivision that includes a private road shall clearly state that such road is a private road.  Further, the initial purchaser of a newly created lot served by a private road shall be furnished by the seller with a disclosure statement outlining the maintenance responsibilities for the road.  [LDR Sec. 30-237 (c)(6)]\nProvide a copy of the Disclosure Statement for review.','\n',char(10)),'Plat updated to clearly indicate Tract A is a private right-of-way. Language in the HOA CCRs state the road maintenance and responsibility lies with the HOA. Proof of documents being acknowledged at the time of sale can be provided upon request.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(69,6,'2026-08-06T23:15:28.336Z','2026-08-12T13:56:34.259Z','Nathan White','Nathan White','1','All drainage easements need to grant ingress/egress to the City.','Ingress and egress is given to the city via note #8.','Water Resources - Utility Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(70,6,'2026-08-06T23:15:28.337Z','2026-08-12T13:56:34.262Z','Nathan White','Nathan White','11',replace('The Proposed Plat does not match the Preliminary Plat nor the Site Plan.\nThe final plat shall conform to the approved preliminary plat and shall meet the platting requirements of Florida Statutes Chapter 177 and the requirements of this section.  [Land Development Regulation (LDR) Section 34-173 (a)]\nThe proposed Lot Area and Lot Widths have changed.  Variance #21-2025 was approved with a minimum Lot Area of 1,830 sqft.  The proposed lot area of several lots is now 1,790 sqft.\nUpdate the proposed Final Plat to conform to the Preliminary Plat and Site Plan or submit a revised Site Plan and Preliminary Plat for review.','\n',char(10)),'A revised site plan and PSP have been submitted to the city prior to the submittal of this revised final plat.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(71,7,'2026-08-14T01:17:52.714Z','2026-08-14T01:20:14.938Z','Nathan White','Nathan White','2','Please provide the elevation at the crown of all adjacent roadways and alleys. Please show this elevation on the topographic survey to demonstrate the FFE of the construction is at minimum 18" above the crown of the adjacent roadways/alleys.','Elevations at crown of road are shown. FFE of ADU is 18" above the crown of road.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(72,7,'2026-08-14T01:17:52.722Z','2026-08-14T01:20:14.961Z','Nathan White','Nathan White','1','Please provide an original topographic survey up to 25 feet from the boundary of the property per the City of Orlando Engineering Standards Manual (ESM) Section 7.01. The topographic survey must be signed and sealed by a surveyor and include the survey datum (NAVD 88) and official benchmarks. A list of acceptable benchmarks includes City of Orlando, Orange County, NGS (National Geodetic Survey), FDOT (Published Benchmarks, not GPS Network referred to as FPRN), FDEP Benchmarks, Virgin Trains Control Network as long as the reference material is sent with the benchmarks. Benchmarks that are NOT accepted include temporary Benchmarks, Site Benchmarks, Land Survey Monuments, Assumed Elevations, etc.','A boundary & topographic survey has been provided. Survey is based on SJRWMD benchmark 08-07-007-0 per surveyor note 4.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(73,7,'2026-08-14T01:18:14.139Z','2026-08-14T01:20:14.958Z','Nathan White','Nathan White','3','Please show the distance from the proposed work to all adjacent property lines.','Site plan created and distances shown.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(74,7,'2026-08-14T01:20:14.854Z','2026-08-14T01:20:14.854Z','Nathan White','Nathan White','4','Buildings/Structures must be a minimum of 5 ft from adjacent property lines.','ADU meets and exceeds requirement.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(75,7,'2026-08-14T01:20:14.858Z','2026-08-14T01:38:44.795Z','Nathan White','Nathan White','8','Please provide a note on the plans that states, "The City of Orlando''s Guidelines for Erosion Sediment Control (aka The Blue Sheet) will serve as a guide for the implementation of erosion sediment control measures."','Note added.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(76,7,'2026-08-14T01:20:14.860Z','2026-08-14T01:38:44.810Z','Nathan White','Nathan White','7','Please state on the plans that the "Sidewalk shall use 3,000 psi Class 1 concrete and thickness shall be 4" thick. Sidewalk shall extend across the driveway. Sidewalk within the driveway shall be 6" thick."','Note added.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(77,7,'2026-08-14T01:20:14.855Z','2026-08-14T01:38:44.799Z','Nathan White','Nathan White','6','The proposed construction falls into the definition of Substantial Improvement/Substantial Enlargement as Section 66.200, Municipal Code for the City of Orlando. Sidewalk construction shall be required at the time of any substantial improvement/enlargement.  Please resubmit plans showing sidewalk construction along the public Right of Way with a note indicating that the "Sidewalk shall use 3,000 psi Class 1 concrete and thickness shall be 4" thick." Please be advised that the portion of the sidewalk in the driveway shall use 3,000 psi Class 1 concrete but must be at least 6 inches in thickness and with a break and exposed joint at the property line.','Sidewalk added to Site Plan.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(78,7,'2026-08-14T01:20:14.859Z','2026-08-14T01:38:44.773Z','Nathan White','Nathan White','5','Please be advised that in established neighborhoods, the existing drainage pattern should not be excessively modified by new constructions. The proposed elevations should not adversely impact adjacent properties with future increment of run-off as well. Is the site getting regraded? If some modifications to existing grade are necessary, please include the proposed grade elevations. If there are no modifications, please show the existing spot elevations on the site plan and state on the plan sheet "there will be no changes to the grading/existing site elevations."','Grading plan created.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(79,7,'2026-08-14T01:38:44.299Z','2026-08-14T01:38:44.299Z','Nathan White','Nathan White','16','Please show the dimensions of the LID on the site plan to verify the volume.','Information added.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(80,7,'2026-08-14T01:38:44.300Z','2026-08-14T01:39:30.264Z','Nathan White','Nathan White','18','For questions regarding Engineering Site issues contact Michael Barton at (407) 246-3978 or michael.barton@orlando.gov. Walk-In meetings will not  be allowed due to the number of reviews we receive and/or previously scheduled meetings. Please be advised, the City of Orlando Erosion Control Sheet (aka Blue Sheet) must be followed during demolition and construction.','Acknowledged','Site Engineering','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(81,7,'2026-08-14T01:38:44.292Z','2026-08-14T01:38:44.292Z','Nathan White','Nathan White','10','Please provide a Civil Grading Plan.','Grading plan created.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(82,7,'2026-08-14T01:38:44.326Z','2026-08-14T01:38:44.326Z','Nathan White','Nathan White','22','Provide the breakdown in the impervious surface ratio calculations to include the ADU. The breakdown should include what is existing and proposed.','ISR worksheet provided.','Engineering Zoning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(83,7,'2026-08-14T01:38:44.301Z','2026-08-14T01:38:44.301Z','Nathan White','Nathan White','14','Please provide the LID calculation on the site plan.','Calculations added','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(84,7,'2026-08-14T01:38:44.302Z','2026-08-14T01:38:44.302Z','Nathan White','Nathan White','21','Additional comments are possible upon submittal of revisions to all Plan Reviewer comments. For questions, please contact Ebony Bernard ebony.bernard@orlando.gov or by phone at (407) 246-3690','Acknowledged','Engineering Zoning','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(85,7,'2026-08-14T01:38:44.336Z','2026-08-14T01:38:44.336Z','Nathan White','Nathan White','23','Sec. 58.984 Provide the setback for the A/C unit to meet the code section.','A/C Pad location and screen bushes added.','Engineering Zoning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(86,7,'2026-08-14T01:38:44.330Z','2026-08-14T01:38:44.330Z','Nathan White','Nathan White','17','The LID/grading plans must be signed and sealed by a Professional Engineer or Registered Architect.','Required party has signed the plan.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(87,7,'2026-08-14T01:38:44.330Z','2026-08-14T01:38:44.330Z','Nathan White','Nathan White','9','Please upload the City of Orlando Erosion and Sedimentation Control sheet (aka Blue Sheet) with your permit submittal. The Blue Sheet can be downloaded at https://www.orlando.gov/files/sharedassets/public/departments/edv/permitt ing-services-division/trade-and-others/erosion-sedimentation-control-blue-sheet.pdf','Document given to client for their upload.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(88,7,'2026-08-14T01:38:44.319Z','2026-08-14T01:38:44.319Z','Nathan White','Nathan White','11','Per Section 7.01.A.4, roof drainage must be collected and conveyed to gutters on lots for which the side yard setback is less than 10''. Site plan must show where the roof downspouts are located. These downspouts should direct the water away from the building and adjacent lots. Please mark arrows for the downspouts direction. Please add a note on the Plot Plan with the following statement “Gutters and downspouts will be added to the building structure. Downspouts shall be directed away from adjacent properties and towards the road/alley."','Information and note added.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(89,7,'2026-08-14T01:38:44.331Z','2026-08-14T01:39:30.269Z','Nathan White','Nathan White','','Comments 25 through 29 not answered in this submittal document.','Architect of Record to answer.','','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(90,7,'2026-08-14T01:38:44.335Z','2026-08-14T01:38:44.335Z','Nathan White','Nathan White','20','[not included]','Acknowledged','Impact Fees','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(91,7,'2026-08-14T01:38:44.337Z','2026-08-14T01:38:44.337Z','Nathan White','Nathan White','13','Please be advised "additional impervious" will be measured by the definition provided in the City of Orlando ESM 7.01.C','Acknowledged.','Site Engineering','not a comment');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(92,7,'2026-08-14T01:38:44.340Z','2026-08-14T01:38:44.340Z','Nathan White','Nathan White','12',replace('Due to issues with flooding in established neighborhoods, please provide some form of Low Impact Development (LID) for this site (i.e. bioretention facilities, rain barrels, storage swales, or other approved method).\nDemonstrate that the stormwater runoff from the impervious area shall be captured through the LID prior to discharge onto the Public ROW or continuing it''s natural flow pattern. LID should capture 1.25" x the impervious surface area if located within the SJRWMD or 50% of 2.5" x the impervious surface area if located within the SFWMD.','\n',char(10)),'Retention swale added. Property lies in SJRWMD. Design retention swale holds 1.41% of the additional impervious area.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(93,7,'2026-08-14T01:38:44.345Z','2026-08-14T01:38:44.345Z','Nathan White','Nathan White','15','Please show the location of the LID and delineation if storage swales are used. Please show the top and bottom elevations of any storage swales. Please provide cross sections if storage swales will be used.','Information added.','Site Engineering','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(94,7,'2026-08-14T01:38:44.343Z','2026-08-14T01:38:44.343Z','Nathan White','Nathan White','24','Please clarify if there is a walkway for the proposed ADU entrance','There is no walkway being installed to the proposed ADU enterence.','Engineering Zoning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(95,7,'2026-08-14T01:38:44.359Z','2026-08-14T01:39:30.268Z','Nathan White','Nathan White','19','Provide the setback distance from the mechanical equipment to the rear property line. Standards of LDC 58.984-985 shall apply.','A/C Pad location and screen bushes added.','Planning','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(96,8,'2026-09-01T01:50:32.208Z','2026-09-01T01:50:32.208Z','Nathan White','Nathan White','1','On the proposed Plat Cover Sheet, the Legal Description, at the end of the legal description, after the point of beginning, add the acreage and square footage.','Information added.','','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(97,8,'2026-09-01T01:50:32.237Z','2026-09-03T18:49:25.246Z','Nathan White','Nathan White','3','The Proposed Plat does not match the Preliminary Plat nor the Site Plan. [further comment text omitted]','All plans are being submitted for bulk approval.','','answered');
