INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(101,8,'2026-09-01T01:59:41.139Z','2026-09-03T18:49:25.251Z','Nathan White','Nathan White','9','Within the declaration of Covenants, page 1, the Architectural Control Committee (ACC) is defined. However, on page 11, the acronym "ARC" is being utilized instead of "ACC".','Typos corrected','','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(102,8,'2026-09-01T01:59:41.137Z','2026-09-01T01:59:41.137Z','Nathan White','Nathan White','4','On the proposed plat, lot number 8, 9, 10, 11, and 12, all of the same lot area and five (5) of them are incorrect. Furthermore, lot numbers 18, 47, 48 have incorrect lot areas.','Lot areas verified and updated.','','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(103,8,'2026-09-01T01:59:41.138Z','2026-09-03T18:49:25.261Z','Nathan White','Nathan White','8','On the Impervious Calculation Sheet, expound/explain the following columns: (a) Allowable Impervious Area (calculated); How did you come up with this number? (b) Additional allowed impervious area; Where did this extra come from? (c) Percentage allowable impervious area? (d) Percentage projected impervious area? [further comment text omitted]','Calculations updated.','','answered');
INSERT INTO "comments" ("id","package","created_date","updated_date","created_by","updated_by","comment_id","comment_text","response_text","department","status") VALUES(104,8,'2026-09-01T01:59:41.139Z','2026-09-01T01:59:41.139Z','Nathan White','Nathan White','7','On the Plat Cover Sheet, the required front yard and side corner yard setbacks are not identified [further comment text omitted]','Front yard setbacks added. Side yard setbacks are not required as no residential lot side line is shared with Tract A or any other public right-of-way.','','answered');
