INSERT INTO "project_tasks" ("id","qbo_project_id","name","scope_of_work","contract_amount_cents","retainer_cents","price_type","sort_order","active","created_date","updated_date","created_by","updated_by") VALUES(1,'181','Boundary Survey','White Point Survey will prepare a boundary survey in conformance with Chapter 5J-17, Florida Administrative Codes, pursuant to Chapter 472, Florida Statutes. The survey will be tied to the Florida State Plane Coordinate System based on the North American Datum of 1983 (NAD 83), 2011 Adjustment, Florida East zone. The survey will show located or set property corners. Improvements on the subject property will be located and shown on the survey. Improvements where the surveyor does not have reasonable access to will not be included. No elevations will be collected or shown on the survey. The survey will show the property''s relation to the FEMA floodplain. The results of the survey will be represented by a survey map being either digitally signed or physically signed by a license surveyor.',200000,100000,'Fixed Fee',0,1,'2026-08-07T21:57:55.618Z','2026-08-07T21:57:55.618Z','1ea572c7-5a13-4519-806d-e2ad849b7d76','1ea572c7-5a13-4519-806d-e2ad849b7d76');
