INSERT INTO "project_tasks" ("id","qbo_project_id","name","scope_of_work","contract_amount_cents","retainer_cents","price_type","sort_order","active","created_date","updated_date","created_by","updated_by") VALUES(33,'193','Topographic Survey','White Point Survey will prepare a topographic survey in conformance with Chapter 5J-17, Florida Administrative Codes, pursuant to Chapter 472, Florida Statutes. The survey will be tied to the Florida State Plane Coordinate System based on the North American Datum of 1983 (NAD 83), 2011 Adjustment, Florida East zone. Elevations will be based on the North American Vertical Datum of 1988 (NAVD 88). The survey will measure all reasonable improvements within the upland area. No storm water or sanitary sewer structures will be measured as part of this survey. The survey will show the property''s relation to the FEMA floodplain. The results of the survey will be represented by a survey map being either digitally signed or physically signed by a license surveyor.',20000,10000,'Fixed Fee',1,1,'2026-08-19T18:42:31.985Z','2026-08-19T18:42:31.985Z','1ea572c7-5a13-4519-806d-e2ad849b7d76','1ea572c7-5a13-4519-806d-e2ad849b7d76');
