INSERT INTO "project_tasks" ("id","qbo_project_id","name","scope_of_work","contract_amount_cents","retainer_cents","price_type","sort_order","active","created_date","updated_date","created_by","updated_by") VALUES(42,'199','Topographic Survey','White Point Survey will prepare a topographic survey in conformance with Chapter 5J-17, Florida Administrative Codes, pursuant to Chapter 472, Florida Statutes. The survey will be tied to the Florida State Plane Coordinate System based on the North American Datum of 1983 (NAD 83), 2011 Adjustment, Florida East zone. Elevations will be based on the North American Vertical Datum of 1988 (NAVD 88). The survey will measure all reasonable improvements on the entire property, along with 15.00 feet beyond the property boundary or to the edge of pavement, whichever is less. The inverts of storm water and sanitary sewer structures within reasonable access will be measured as part of this survey. No lane closures or traffic control will be provided as part of this survey. The survey will show the property''s relation to the FEMA floodplain. The results of the survey will be represented by a survey map being either digitally signed or physically signed by a license surveyor.',170000,42500,'Fixed Fee',1,1,'2026-08-28T14:05:04.731Z','2026-08-28T14:05:04.731Z','1ea572c7-5a13-4519-806d-e2ad849b7d76','1ea572c7-5a13-4519-806d-e2ad849b7d76');
